# Serves the instrumented Home page, logs what it reports, saves page snapshots.
import http.server, sys, os, urllib.parse, time
root, port = sys.argv[1], int(sys.argv[2])
os.chdir(root)
class H(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
    def end_headers(self):
        self.send_header('Access-Control-Allow-Origin', '*'); super().end_headers()
    def do_OPTIONS(self):
        self.send_response(204); self.send_header('Access-Control-Allow-Headers', '*'); self.end_headers()
    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        if u.path == '/log':
            with open('log.txt', 'a') as f: f.write(time.strftime('%H:%M:%S ') + urllib.parse.unquote(u.query) + '\n')
            self.send_response(204); self.end_headers(); return
        return super().do_GET()
    def do_POST(self):
        u = urllib.parse.urlparse(self.path)
        name = urllib.parse.parse_qs(u.query)['name'][0]
        body = self.rfile.read(int(self.headers['Content-Length']))
        os.makedirs('snaps', exist_ok=True)
        open(os.path.join('snaps', name + '.html'), 'wb').write(body)
        self.send_response(204); self.end_headers()
http.server.ThreadingHTTPServer(('127.0.0.1', port), H).serve_forever()
EOF
cat > $S/drive/inject.js <<'EOF'
<script>
(function () {
  var base = 'http://127.0.0.1:' + location.port;
  var skip = /[?&]skip=1/.test(location.search);
  function log(s) { try { fetch(base + '/log?' + encodeURIComponent(s)); } catch (e) {} }
  function snap(name) {
    var html = '<!doctype html>' + document.documentElement.outerHTML;
    fetch(base + '/snap?name=' + name, { method: 'POST', body: html });
    log('snap ' + name);
  }
  var last = null;
  function wrap() {
    var b = window.__jusprinBridge;
    if (!b || b.__wrapped) return;
    var d = b.deliver;
    b.deliver = function (env) {
      try {
        var e = typeof env === 'string' ? JSON.parse(env) : env;
        if (e && e.type === 'state') {
          var o = e.payload.onboarding || {};
          var printers = (e.payload.printers || e.payload.rail || {});
          last = 'state onboarding.visible=' + o.visible + ' step=' + o.step + ' printersScreen=' + o.printersScreen +
            ' app=' + (o.printerImport && o.printerImport.app) + ' printers=' + JSON.stringify((o.printerImport && o.printerImport.printers) || []);
          log(last);
        } else if (e && e.type) log('envelope ' + e.type + ' ' + JSON.stringify(e.payload || {}).slice(0, 300));
      } catch (x) { log('wrap error ' + x); }
      return d.apply(this, arguments);
    };
    b.__wrapped = true;
    log('wrapped bridge');
  }
  function button(text) {
    return Array.prototype.find.call(document.querySelectorAll('button'), function (x) { return x.textContent.trim() === text; });
  }
  function hasText(t) { return document.body && document.body.innerText.indexOf(t) >= 0; }
  var phase = 'welcome', ticks = 0;
  setInterval(function () {
    wrap(); ticks++;
    if (phase === 'welcome' && button('Just slice for now')) { log('click Just slice for now'); button('Just slice for now').click(); phase = 'printers'; ticks = 0; }
    else if (phase === 'printers' && hasText('Bring your printers from') && ticks > 6) {
      snap('import-screen'); log('buttons: ' + Array.prototype.map.call(document.querySelectorAll('button'), function (x) { return x.textContent.trim(); }).join(' | '));
      phase = skip ? 'skip' : 'done'; ticks = 0;
    }
    else if (phase === 'skip' && ticks > 3) {
      var s = button('Skip for now');
      log(s ? 'click Skip for now' : 'NO Skip for now button');
      if (s) s.click();
      phase = 'home'; ticks = 0;
    }
    else if (phase === 'home' && ticks > 20) { snap('after-skip'); log('page text: ' + document.body.innerText.replace(/\s+/g, ' ').slice(0, 400)); phase = 'done'; }
    else if (phase === 'start-home' && ticks > 20) { snap('next-launch'); log('page text: ' + document.body.innerText.replace(/\s+/g, ' ').slice(0, 400)); phase = 'done'; }
  }, 500);
  if (/[?&]relaunch=1/.test(location.search)) phase = 'start-home';
})();
</script>
EOF
echo ok

